    colors = sorted(counts)
    weights = [counts[c] for c in colors]
    rng = random.Random(2)
    out = [[rng.choices(colors, weights=weights, k=1)[0] for _ in range(2*w)] for _ in range(2*h)]
    for r in range(h):
        out[r][:w] = grid[r][:]
    return out

